import{_ as r,C as o,o as a,c as n,a2 as c,b as d,w as i,a as s,E as l,a3 as f}from"./chunks/framework.DZUUNQ77.js";const S=JSON.parse('{"title":"wifi_scanner · WiFi 扫描代理","description":"","frontmatter":{},"headers":[],"relativePath":"reference/proxies/wifi_scanner.md","filePath":"reference/proxies/wifi_scanner.md","lastUpdated":1784063681000}'),h={name:"reference/proxies/wifi_scanner.md"};function p(E,e,u,A,m,_){const t=o("Mermaid");return a(),n("div",null,[e[1]||(e[1]=c('<h1 id="wifi-scanner-·-wifi-扫描代理" tabindex="-1">wifi_scanner · WiFi 扫描代理 <a class="header-anchor" href="#wifi-scanner-·-wifi-扫描代理" aria-label="Permalink to &quot;wifi_scanner · WiFi 扫描代理&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><a href="https://github.com/android-security-engineer/VirtualXposed-skills/tree/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/client/hook/proxies/wifi_scanner" target="_blank" rel="noreferrer"><code>src/main/java/com/lody/virtual/client/hook/proxies/wifi_scanner/</code></a>（2 个文件）</p></div><p>拦截 <code>WifiScanner</code>（WiFi 扫描服务，用于定位）。共 2 个文件。</p><h2 id="文件组成" tabindex="-1">文件组成 <a class="header-anchor" href="#文件组成" aria-label="Permalink to &quot;文件组成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>WifiScannerStub.java</code></td><td>主代理，用 <code>GhostWifiScannerImpl</code> 直接替换 <code>sCache[&quot;wifiscanner&quot;]</code>——<strong>整服务被接管</strong>而非方法拦截</td></tr><tr><td><code>GhostWifiScannerImpl.java</code></td><td>&quot;幽灵&quot; <code>IWifiScanner.Stub</code> 实现，提供空的扫描结果源</td></tr></tbody></table><h2 id="接管机制" tabindex="-1">接管机制 <a class="header-anchor" href="#接管机制" aria-label="Permalink to &quot;接管机制&quot;">​</a></h2><p>不同于普通代理（拦方法、改参数后放行），<code>WifiScannerStub</code> 把整个 <code>IWifiScanner</code> 替换为 <code>GhostWifiScannerImpl</code>。<code>getMessenger</code> 返回一个空 <code>Handler</code> 的 Messenger，<code>getAvailableChannels</code> 返回空列表——App 拿不到真实扫描结果，使基于 WiFi 扫描的定位失效或落到伪造坐标。</p><h2 id="与虚拟定位的关系" tabindex="-1">与虚拟定位的关系 <a class="header-anchor" href="#与虚拟定位的关系" aria-label="Permalink to &quot;与虚拟定位的关系&quot;">​</a></h2><p>WiFi 扫描结果常被用于基于 AP MAC 的定位反查。<code>GhostWifiScannerImpl</code> 配合 <a href="./../../features/virtual-location">虚拟定位</a> 返回伪造的扫描结果，使基于 WiFi 的定位也落在伪造坐标。</p><h2 id="拦截与转发流程" tabindex="-1">拦截与转发流程 <a class="header-anchor" href="#拦截与转发流程" aria-label="Permalink to &quot;拦截与转发流程&quot;">​</a></h2>',10)),(a(),d(f,null,{default:i(()=>[l(t,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20LR%0A%20%20APP%5B%22%E7%9B%AE%E6%A0%87%20App%22%5D%20--%3E%7C%22IWifiScanner%20%E8%B0%83%E7%94%A8%22%7C%20GHOST%5B%22GhostWifiScannerImpl%3Cbr%2F%3E(%E6%95%B4%E6%9C%8D%E5%8A%A1%E6%8E%A5%E7%AE%A1)%22%5D%0A%20%20GHOST%20--%3E%7C%22getMessenger%22%7C%20EMPTY%5B%22%E7%A9%BA%20Handler%22%5D%0A%20%20GHOST%20--%3E%7C%22getAvailableChannels%22%7C%20NILL%5B%22%E7%A9%BA%E5%88%97%E8%A1%A8%22%5D%0A%20%20GHOST%20-.-%3E%7C%22%E5%B1%8F%E8%94%BD%E7%9C%9F%E5%AE%9E%E6%89%AB%E6%8F%8F%22%7C%20LOC%5B%22%E9%85%8D%E5%90%88%E8%99%9A%E6%8B%9F%E5%AE%9A%E4%BD%8D%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1}))])}const C=r(h,[["render",p]]);export{S as __pageData,C as default};
